// Layout: two columns joined by a 180px gap for the "returns" arrow.
// Left container "App component" x 40..380, y 80..380 holds the code.
// Right container "Element tree" x 560..920, y 80..380 holds the tree:
//   root <div> centered at x 740 (y 140), children <h1> x 584..724 and <button> x 756..896 at y 276.
// Note centered below at y 410.
const tl = h.timeline();

const codeArea = h.container({ x: 40, y: 80, w: 340, h: 300, label: 'App component', role: 'neutral' });
const src = h.code({
  x: 64, y: 124, w: 292, title: 'App.jsx',
  lines: [
    'function App() {',
    '  return (',
    '    <div>',
    '      <h1>Hello</h1>',
    '      <button>Save</button>',
    '    </div>',
    '  );',
    '}'
  ]
});

const treeArea = h.container({ x: 560, y: 80, w: 360, h: 300, label: 'Element tree', role: 'neutral' });
const divBox = h.box({ x: 670, y: 140, w: 140, h: 56, label: '<div>', role: 'neutral' });
const h1Box = h.box({ x: 584, y: 276, w: 140, h: 64, label: '<h1>', sub: '"Hello"', role: 'neutral' });
const btnBox = h.box({ x: 756, y: 276, w: 140, h: 64, label: '<button>', sub: '"Save"', role: 'neutral' });
const e1 = h.line(divBox, h1Box, { role: 'neutral' });
const e2 = h.line(divBox, btnBox, { role: 'neutral' });

const ret = h.arrow(codeArea, treeArea, { label: 'returns', role: 'accent' });
const n = h.note({ x: 300, y: 412, w: 360, text: 'Just light descriptions. Nothing is on the page yet.', role: 'accent' });

// Hide the tree pieces until they are built
gsap.set([treeArea, divBox, h1Box, btnBox, e1, e2, ret, n], { opacity: 0 });

// 1) Set the scene: the component code
h.reveal(tl, [codeArea, src], 0, { from: 'up' });
h.highlightLine(tl, src, 1, '>0.4');

// 2) The one change: code turns into a tree of element boxes
h.draw(tl, ret, '>0.3');
h.reveal(tl, treeArea, '<0.2');

h.highlightLine(tl, src, 2, '>0.3');
h.reveal(tl, divBox, '<', { from: 'scale' });
h.recolor(tl, divBox, 'active', '<');

h.highlightLine(tl, src, 3, '>0.4');
h.reveal(tl, e1, '<');
h.reveal(tl, h1Box, '<0.2', { from: 'down' });
h.recolor(tl, h1Box, 'active', '<');
h.recolor(tl, divBox, 'neutral', '<');

h.highlightLine(tl, src, 4, '>0.4');
h.reveal(tl, e2, '<');
h.reveal(tl, btnBox, '<0.2', { from: 'down' });
h.recolor(tl, btnBox, 'active', '<');
h.recolor(tl, h1Box, 'neutral', '<');

h.recolor(tl, btnBox, 'neutral', '>0.4');
h.pulse(tl, [divBox, h1Box, btnBox], '<');

h.reveal(tl, n, '>0.4', { from: 'up' });
h.wait(tl, 2);
return tl;

// Layout plan:
// Top half: the element tree, centred on x 480 with the same box sizes as step 1.
//   The heading "Element tree" sits at y 42.
//   The <div> box spans x 410..550 at y 72..120.
//   The <h1> box spans x 314..454 and the <button> box spans x 506..646, both at y 148..204.
// Bottom half: the "Real DOM" container at x 200..760, y 326..500.
//   Inside it, a DOM <div> region spans x 280..680, y 364..492.
//   It holds a DOM <h1> at x 314..454 and a DOM <button> at x 506..646, both at y 408..464.
// "create" arrows run straight down at x 384, 480 and 576. Their label pills land at y ~240 and y ~306.
// Ending: the arrows fade, the tree is renamed "Previous tree" and slides left by 274px. A note appears on the right.
const tl = h.timeline();

// Element tree (same sizes and roles as step 1)
const heading = h.text({ x: 480, y: 42, text: 'Element tree', size: 'label', anchor: 'middle' });
const divBox = h.box({ x: 410, y: 72, w: 140, h: 48, label: '<div>', role: 'neutral' });
const h1Box = h.box({ x: 314, y: 148, w: 140, h: 56, label: '<h1>', sub: '"Hello"', role: 'neutral' });
const btnBox = h.box({ x: 506, y: 148, w: 140, h: 56, label: '<button>', sub: '"Save"', role: 'neutral' });
const e1 = h.line(divBox, h1Box, { role: 'neutral' });
const e2 = h.line(divBox, btnBox, { role: 'neutral' });

// Real DOM area and the nodes that will be created inside it
const realDom = h.container({ x: 200, y: 326, w: 560, h: 174, label: 'Real DOM', role: 'neutral' });
const domDiv = h.container({ x: 280, y: 364, w: 400, h: 128, label: '<div>', role: 'new' });
const domH1 = h.box({ x: 314, y: 408, w: 140, h: 56, label: '<h1>', sub: '"Hello"', role: 'new' });
const domBtn = h.box({ x: 506, y: 408, w: 140, h: 56, label: '<button>', sub: '"Save"', role: 'new' });

// "create" arrows from each element down to its DOM node
const cDiv = h.arrow(divBox, domDiv, { label: 'create', role: 'new', fromSide: 'bottom', toSide: 'top' });
const cH1 = h.arrow(h1Box, domH1, { label: 'create', role: 'new', fromSide: 'bottom', toSide: 'top' });
const cBtn = h.arrow(btnBox, domBtn, { label: 'create', role: 'new', fromSide: 'bottom', toSide: 'top' });

const n = h.note({ x: 620, y: 96, w: 280, text: 'Remembered, to compare with the next render.', role: 'accent' });

gsap.set([heading, divBox, h1Box, btnBox, e1, e2, realDom, domDiv, domH1, domBtn, cDiv, cH1, cBtn, n], { opacity: 0 });

// 1) Set the scene: the tree from step 1, plus an empty page
h.reveal(tl, [heading, divBox, e1, e2, h1Box, btnBox], 0, { stagger: 0.05 });
h.reveal(tl, realDom, '>0.2', { from: 'up' });

// 2) The one change: a real DOM node is created for every element
h.recolor(tl, divBox, 'active', '>0.4');
h.draw(tl, cDiv, '<');
h.reveal(tl, domDiv, '>-0.2', { from: 'scale' });
h.recolor(tl, divBox, 'neutral', '>0.2');

h.recolor(tl, h1Box, 'active', '<');
h.draw(tl, cH1, '<');
h.reveal(tl, domH1, '>-0.2', { from: 'scale' });
h.recolor(tl, h1Box, 'neutral', '>0.2');

h.recolor(tl, btnBox, 'active', '<');
h.draw(tl, cBtn, '<');
h.reveal(tl, domBtn, '>-0.2', { from: 'scale' });
h.recolor(tl, btnBox, 'neutral', '>0.2');

h.pulse(tl, [domDiv, domH1, domBtn], '>0.2');

// 3) The tree is kept as the "Previous tree"
h.hide(tl, [cDiv, cH1, cBtn], '>0.5');
h.swapText(tl, heading, 'Previous tree', '>0.2');
const treeParts = [heading, divBox, h1Box, btnBox, e1, e2];
treeParts.forEach((el, i) => {
  h.moveBy(tl, el, { dx: -274, dy: 0 }, i === 0 ? '>0.3' : '<');
});
h.reveal(tl, n, '>0.3', { from: 'up' });
h.wait(tl, 2);
return tl;

// Layout: two columns joined by a 200px gap for the "re-render" arrow.
// Left container "Previous tree" x 40..380, y 80..400. Right container "New tree" x 580..920, y 80..400.
// Inside each tree (offset +540 on the right):
//   App box x 100..220 (y 120..168), accent state tag pill x 248..352 (y 128..160), "state change" label below the tag (y 178).
//   <div> x 140..280 (y 208..256), children <h1> x 60..190 and <button> x 230..360 at y 300..364.
// Note centred below at y 428.
const tl = h.timeline();

function buildTree(ox, title, tagText, btnText) {
  const area = h.container({ x: 40 + ox, y: 80, w: 340, h: 320, label: title, role: 'neutral' });
  const app = h.box({ x: 100 + ox, y: 120, w: 120, h: 48, label: 'App', role: 'neutral' });
  const tag = h.box({ x: 248 + ox, y: 128, w: 104, h: 32, label: tagText, role: 'accent', shape: 'pill', size: 'small' });
  const div = h.box({ x: 140 + ox, y: 208, w: 140, h: 48, label: '<div>', role: 'neutral' });
  const h1 = h.box({ x: 60 + ox, y: 300, w: 130, h: 64, label: '<h1>', sub: '"Hello"', role: 'neutral' });
  const btn = h.box({ x: 230 + ox, y: 300, w: 130, h: 64, label: '<button>', sub: btnText, role: 'neutral' });
  const l0 = h.line(app, div, { role: 'neutral' });
  const l1 = h.line(div, h1, { role: 'neutral' });
  const l2 = h.line(div, btn, { role: 'neutral' });
  return { area, app, tag, div, h1, btn, l0, l1, l2 };
}

const prev = buildTree(0, 'Previous tree', 'count: 0', '"Clicked 0"');
const next = buildTree(540, 'New tree', 'count: 1', '"Clicked 1"');

const stateLbl = h.text({ x: 300, y: 178, text: 'state change', size: 'small', anchor: 'middle', role: 'accent' });
const rerender = h.arrow(prev.area, next.area, { label: 're-render', role: 'accent' });
const n = h.note({ x: 300, y: 428, w: 360, text: 'A brand-new tree. The previous one is kept to compare.', role: 'accent' });

const nextAll = [next.area, next.app, next.tag, next.div, next.h1, next.btn, next.l0, next.l1, next.l2];
gsap.set([...nextAll, stateLbl, rerender, n], { opacity: 0 });

// 1) Set the scene: the remembered previous tree
h.reveal(tl, [prev.area, prev.app, prev.tag, prev.l0, prev.div, prev.l1, prev.l2, prev.h1, prev.btn], 0, { stagger: 0.05 });

// 2) State changes on App
const ring = h.highlight(tl, prev.tag, '>0.4', { role: 'active', pad: 6 });
h.reveal(tl, stateLbl, '<', { from: 'up' });
h.swapText(tl, prev.tag, 'count: 1', '>0.3');
h.recolor(tl, prev.app, 'active', '<');
h.pulse(tl, prev.tag, '>0.1');

// 3) The one change: re-render produces a new tree beside the old one
h.draw(tl, rerender, '>0.4');
h.reveal(tl, next.area, '<0.3');
h.reveal(tl, [next.app, next.tag], '>0.1', { from: 'scale' });
h.reveal(tl, [next.l0, next.div], '>0.1', { from: 'down' });
h.reveal(tl, [next.l1, next.l2, next.h1, next.btn], '>0.1', { from: 'down', stagger: 0.1 });

// 4) Show what differs: the button text
h.hide(tl, ring, '>0.3');
h.recolor(tl, prev.app, 'neutral', '<');
h.recolor(tl, next.btn, 'new', '>0.2');
h.pulse(tl, next.btn, '>0.1');

h.reveal(tl, n, '>0.4', { from: 'up' });
h.wait(tl, 2);
return tl;

// Layout: two columns with a 200px middle gap, matching the tree steps.
// Left "Perfect comparison" container x 40..380, right "React's rules" x 580..920, both y 56..336.
//   Bars share a baseline at y 316: tall bar x 140..280 (y 96..316), short bar x 680..820 (y 252..316).
// Middle: "vs" label at x 480, y 186.
// Below left: one note x 40..380, y 360. Below right: two rule cards x 580..920, y 360..416 and 440..496.
const tl = h.timeline();

// Left: perfect comparison
const perfArea = h.container({ x: 40, y: 56, w: 340, h: 280, label: 'Perfect comparison', role: 'neutral' });
const tallBar = h.box({ x: 140, y: 96, w: 140, h: 220, label: 'very slow', sub: 'cost grows fast', role: 'old' });

// Right: React's rules
const rulesArea = h.container({ x: 580, y: 56, w: 340, h: 280, label: "React's rules", role: 'neutral' });
const shortBar = h.box({ x: 680, y: 252, w: 140, h: 64, label: 'about one pass', role: 'neutral', size: 'body' });

// Middle
const vs = h.text({ x: 480, y: 186, text: 'vs', size: 'heading', anchor: 'middle', muted: true });

// Note under the left side
const n = h.note({ x: 40, y: 360, w: 340, text: 'Trying every possible match is far too slow for big trees.', role: 'old' });

// Rule cards under the right side
const rule1 = h.box({ x: 580, y: 360, w: 340, h: 56, label: 'Rule 1: type', sub: 'different type = rebuild', role: 'accent' });
const rule2 = h.box({ x: 580, y: 440, w: 340, h: 56, label: 'Rule 2: keys', sub: 'keys identify list items', role: 'accent' });

gsap.set([vs, n, rule1, rule2], { opacity: 0 });

// 1) Scene
h.reveal(tl, [perfArea, rulesArea], 0, { stagger: 0.15, duration: 0.6 });
h.reveal(tl, vs, '>0.1', { from: 'fade', duration: 0.5 });

// Tall bar grows slowly: perfect diffing is expensive
tl.fromTo(tallBar, { scaleY: 0, transformOrigin: '50% 100%' }, { scaleY: 1, duration: 2, ease: 'power1.in' }, '>0.3');
h.reveal(tl, n, '>0.2', { from: 'up' });

// Short bar grows quickly: React's approach
tl.fromTo(shortBar, { scaleY: 0, transformOrigin: '50% 100%' }, { scaleY: 1, duration: 0.6 }, '>0.5');
h.recolor(tl, shortBar, 'new', '>0.2');
h.pulse(tl, shortBar, '>0.1');

// 2) The one change: the two rules appear as React's shortcut
const ring = h.highlight(tl, rulesArea, '>0.4', { role: 'active', pad: 6 });
h.reveal(tl, rule1, '>0.2', { from: 'up' });
h.reveal(tl, rule2, '>0.3', { from: 'up' });
h.pulse(tl, [rule1, rule2], '>0.3');
h.hide(tl, ring, '>0.3');

h.wait(tl, 2);
return tl;

// Layout: same two tree containers as step 4 (taller to fit state tags).
// Left "Previous tree" x 40..380, right "New tree" x 580..920, both y 56..356.
//   Roots (w140,h56) at y 104: left <div> x 140..280, right <section> x 680..820.
//   Counter (w160,h56) at y 212: left x 130..290, right x 670..830.
//   State tags (accent pills) centered under Counter at y 310 (x 210 / x 750).
// Middle: "Different type" label at x 480, y 80; dashed comparison line between roots at y 132.
// Bottom: one note centered, x 300..660, y 400.
const tl = h.timeline();

// Previous tree
const prevArea = h.container({ x: 40, y: 56, w: 340, h: 300, label: 'Previous tree', role: 'neutral' });
const divL = h.box({ x: 140, y: 104, w: 140, h: 56, label: '<div>', role: 'neutral' });
const ctrL = h.box({ x: 130, y: 212, w: 160, h: 56, label: 'Counter', role: 'neutral' });
const eL = h.line(divL, ctrL, { role: 'neutral' });
const tagL = h.token({ x: 210, y: 310, label: 'state: 5', role: 'accent' });

// New tree
const newArea = h.container({ x: 580, y: 56, w: 340, h: 300, label: 'New tree', role: 'neutral' });
const secR = h.box({ x: 680, y: 104, w: 140, h: 56, label: '<section>', role: 'neutral' });
const ctrR = h.box({ x: 670, y: 212, w: 160, h: 56, label: 'Counter', role: 'new' });
const eR = h.line(secR, ctrR, { role: 'new' });
const tagR = h.token({ x: 750, y: 310, label: 'state: 0', role: 'accent' });

// Middle
const diffLabel = h.text({ x: 480, y: 80, text: 'Different type', size: 'label', anchor: 'middle', role: 'active' });
const pair = h.line({ x: 286, y: 132 }, { x: 674, y: 132 }, { role: 'active', dashed: true });

const note = h.note({ x: 300, y: 400, w: 360, text: 'Old subtree destroyed: the new Counter starts fresh.', role: 'accent' });

gsap.set([ctrR, eR, tagR, diffLabel, pair, note], { opacity: 0 });

// 1) Scene
h.reveal(tl, [prevArea, divL, eL, ctrL, tagL, newArea, secR], 0, { stagger: 0.06, duration: 0.6 });

// 2) Compare roots: types differ
h.recolor(tl, [divL, secR], 'active', '>0.4');
h.draw(tl, pair, '<0.2', { duration: 0.8 });
h.reveal(tl, diffLabel, '>0.1', { from: 'down' });
h.pulse(tl, [divL, secR], '>0.2');

// 3) Throw away the old subtree (state included)
h.recolor(tl, [divL, ctrL, eL], 'danger', '>0.5');
h.pulse(tl, tagL, '>0.1');
h.hide(tl, [divL, eL, ctrL, tagL], '>0.4');

// 4) Build the new subtree from scratch
h.recolor(tl, secR, 'new', '>0.3');
h.draw(tl, eR, '>0.1', { duration: 0.6 });
h.reveal(tl, ctrR, '>', { from: 'scale' });
h.reveal(tl, tagR, '>0.2', { from: 'scale' });
h.highlight(tl, tagR, '>0.2', { role: 'new', pad: 6 });

h.reveal(tl, note, '>0.4', { from: 'up' });
h.wait(tl, 2);
return tl;

// Layout: two tree containers side by side with a 200px middle gap (same as step 4).
// Left "Previous tree" x 40..380, right "New tree" x 580..920, both y 56..416.
//   Top pair: <button> boxes (w200,h64) at y 100: left x 110..310, right x 670..870.
//             class tags (pill w140,h36) at y 188: left x 140..280, right x 700..840.
//   Bottom pair: <Counter> boxes (w200,h64) at y 256: left x 110..310, right x 670..870.
//             tags (pill w136,h36) at y 344: label tag left x 64..200 / right x 604..740,
//             state tag left x 224..360 / right x 764..900.
// Middle gap x 380..580: dashed "same type" pair lines at y 132 and y 288,
//   short annotations at y 198 ("class attribute") and y 340 / 366 ("props updated", "state kept").
// Note centered below the containers at y 436.
const tl = h.timeline();

// Previous tree
const prevArea = h.container({ x: 40, y: 56, w: 340, h: 360, label: 'Previous tree', role: 'neutral' });
const btnL = h.box({ x: 110, y: 100, w: 200, h: 64, label: '<button>', sub: 'DOM node', role: 'neutral', shape: 'pill' });
const clsL = h.box({ x: 140, y: 188, w: 140, h: 36, label: "class='blue'", role: 'accent', shape: 'pill', size: 'small' });
const cntL = h.box({ x: 110, y: 256, w: 200, h: 64, label: '<Counter>', sub: 'component', role: 'neutral', shape: 'pill' });
const propL = h.box({ x: 64, y: 344, w: 136, h: 36, label: "label='A'", role: 'accent', shape: 'pill', size: 'small' });
const stL = h.box({ x: 224, y: 344, w: 136, h: 36, label: 'state: 5', role: 'neutral', shape: 'pill', size: 'small' });

// New tree
const newArea = h.container({ x: 580, y: 56, w: 340, h: 360, label: 'New tree', role: 'neutral' });
const btnR = h.box({ x: 670, y: 100, w: 200, h: 64, label: '<button>', sub: 'DOM node', role: 'neutral', shape: 'pill' });
const clsR = h.box({ x: 700, y: 188, w: 140, h: 36, label: "class='blue'", role: 'accent', shape: 'pill', size: 'small' });
const cntR = h.box({ x: 670, y: 256, w: 200, h: 64, label: '<Counter>', sub: 'component', role: 'neutral', shape: 'pill' });
const propR = h.box({ x: 604, y: 344, w: 136, h: 36, label: "label='A'", role: 'accent', shape: 'pill', size: 'small' });
const stR = h.box({ x: 764, y: 344, w: 136, h: 36, label: 'state: 5', role: 'neutral', shape: 'pill', size: 'small' });

// Pair comparison lines
const pairBtn = h.line(btnL, btnR, { role: 'active', dashed: true, label: 'same type' });
const pairCnt = h.line(cntL, cntR, { role: 'active', dashed: true, label: 'same type' });

// Middle annotations
const tClass = h.text({ x: 480, y: 198, text: 'class attribute', size: 'small', anchor: 'middle', role: 'new' });
const tProps = h.text({ x: 480, y: 340, text: 'props updated', size: 'small', anchor: 'middle', role: 'new' });
const tState = h.text({ x: 480, y: 366, text: 'state kept', size: 'small', anchor: 'middle', muted: true });

const n = h.note({ x: 200, y: 436, w: 560, text: 'Same node, same instance: only the changed value is updated.', role: 'accent' });

gsap.set([pairBtn, pairCnt, tClass, tProps, tState, n], { opacity: 0 });

// 1) Scene: both trees already exist
h.reveal(tl, [prevArea, btnL, clsL, cntL, propL, stL, newArea, btnR, clsR, cntR, propR, stR], 0, { stagger: 0.04, duration: 0.6 });

// 2) Top pair: <button> vs <button>
h.recolor(tl, [btnL, btnR], 'active', '>0.4');
h.draw(tl, pairBtn, '<0.2', { duration: 0.8 });
h.recolor(tl, [btnL, btnR], 'neutral', '>0.3');
const ring1 = h.highlight(tl, clsR, '<', { role: 'active', pad: 6 });
h.pulse(tl, clsR, '>0.1');
h.swapText(tl, clsR, "class='red'", '>0.1');
h.recolor(tl, clsR, 'new', '<');
h.recolor(tl, clsL, 'old', '<');
h.reveal(tl, tClass, '<0.2', { from: 'up' });
h.hide(tl, ring1, '>0.3');

// 3) Bottom pair: <Counter> vs <Counter>
h.recolor(tl, [cntL, cntR], 'active', '>0.4');
h.draw(tl, pairCnt, '<0.2', { duration: 0.8 });
h.recolor(tl, [cntL, cntR], 'neutral', '>0.3');
const ring2 = h.highlight(tl, propR, '<', { role: 'active', pad: 6 });
h.pulse(tl, propR, '>0.1');
h.swapText(tl, propR, "label='B'", '>0.1');
h.recolor(tl, propR, 'new', '<');
h.recolor(tl, propL, 'old', '<');
h.reveal(tl, tProps, '<0.2', { from: 'up' });
h.hide(tl, ring2, '>0.3');

// State stays exactly as it was
h.pulse(tl, [stL, stR], '>0.3');
h.reveal(tl, tState, '<', { from: 'up' });

h.reveal(tl, n, '>0.5', { from: 'up' });
h.wait(tl, 2);
return tl;

// Layout: two columns with a 200px middle gap, matching the tree steps.
// Left "Previous tree" container x 40..380, right "New tree" x 580..920, both y 56..436.
// In each column the <ul> box sits at y 100, with item rows below at y 196 / 276 / 356 (h 56, gap 24).
// Left boxes are at x 160..320 and their position labels at x 64. Right boxes are at x 640..800 and their position labels at x 816.
// Position-matching lines run horizontally across the middle gap, with labels near x 480.
// One note is centred below at y 452.
const tl = h.timeline();

const prevArea = h.container({ x: 40, y: 56, w: 340, h: 380, label: 'Previous tree', role: 'neutral' });
const newArea = h.container({ x: 580, y: 56, w: 340, h: 380, label: 'New tree', role: 'neutral' });

const rowY = [196, 276, 356];
const BW = 160, BH = 56;

// Left tree
const ulL = h.box({ x: 160, y: 100, w: BW, h: BH, label: '<ul>', shape: 'pill', role: 'neutral' });
const bobL = h.box({ x: 160, y: rowY[0], w: BW, h: BH, label: 'Bob', sub: '<li>', role: 'neutral' });
const catL = h.box({ x: 160, y: rowY[1], w: BW, h: BH, label: 'Cat', sub: '<li>', role: 'neutral' });
const posL1 = h.text({ x: 64, y: rowY[0] + 20, text: 'position 1', size: 'small', muted: true });
const posL2 = h.text({ x: 64, y: rowY[1] + 20, text: 'position 2', size: 'small', muted: true });

// Right tree
const ulR = h.box({ x: 640, y: 100, w: BW, h: BH, label: '<ul>', shape: 'pill', role: 'neutral' });
const annR = h.box({ x: 640, y: rowY[0], w: BW, h: BH, label: 'Ann', sub: '<li>', role: 'neutral' });
const bobR = h.box({ x: 640, y: rowY[1], w: BW, h: BH, label: 'Bob', sub: '<li>', role: 'neutral' });
const catR = h.box({ x: 640, y: rowY[2], w: BW, h: BH, label: 'Cat', sub: 'created', role: 'new' });
const posR1 = h.text({ x: 816, y: rowY[0] + 20, text: 'position 1', size: 'small', muted: true });
const posR2 = h.text({ x: 816, y: rowY[1] + 20, text: 'position 2', size: 'small', muted: true });
const posR3 = h.text({ x: 816, y: rowY[2] + 20, text: 'position 3', size: 'small', muted: true });

// Matching by position
const m1 = h.line(bobL, annR, { label: 'text changed', role: 'active', fromSide: 'right', toSide: 'left' });
const m2 = h.line(catL, bobR, { label: 'text changed', role: 'active', fromSide: 'right', toSide: 'left' });

const n = h.note({ x: 220, y: 452, w: 520, text: 'Only Ann was added, yet every item gets changed.', role: 'accent' });

gsap.set([catR, m1, m2, n], { opacity: 0 });

// 1) Scene
h.reveal(tl, [prevArea, newArea], 0, { stagger: 0.15, duration: 0.6 });
h.reveal(tl, [ulL, ulR], '>0.1', { from: 'fade', duration: 0.5 });
h.reveal(tl, [bobL, catL, annR, bobR], '>0.1', { from: 'up', stagger: 0.1, duration: 0.5 });
h.reveal(tl, [posL1, posL2, posR1, posR2, posR3], '>0.2', { from: 'fade', stagger: 0.08, duration: 0.5 });

// 2) The change: position 1 is compared with position 1
h.recolor(tl, [bobL, annR], 'active', '>0.5');
h.draw(tl, m1, '<0.1');
h.pulse(tl, [bobL, annR], '>0.1');
h.recolor(tl, bobL, 'neutral', '>0.3');
h.recolor(tl, annR, 'new', '<');

// Position 2 is compared with position 2
h.recolor(tl, [catL, bobR], 'active', '>0.5');
h.draw(tl, m2, '<0.1');
h.pulse(tl, [catL, bobR], '>0.1');
h.recolor(tl, catL, 'neutral', '>0.3');
h.recolor(tl, bobR, 'new', '<');

// Position 3 has nothing to match, so Cat is created
h.reveal(tl, catR, '>0.5', { from: 'scale' });
h.pulse(tl, catR, '>0.1');

h.reveal(tl, n, '>0.5', { from: 'up' });
h.wait(tl, 2);
return tl;

// Layout: same two-container arrangement as earlier steps.
// Left "Previous tree" x 40..380, right "New tree" x 580..920, both y 56..404.
//   Roots <ul> (w140,h56) at y 100: left x 160..300, right x 660..800.
//   List items (w120,h48) at rows y 188 / 260 / 332 (centres 212 / 284 / 356).
//     Left items x 170..290 (Bob, Cat), key tags centred at x 105 (outside edge).
//     Right items x 670..790 (Ann, Bob, Cat), key tags centred at x 855.
// Middle (x 380..580): "match by …" label at x 480, y 72; matching lines cross between items.
// "insert" small label left of Ann at x 628. One note centred below, x 300..660, y 428.
const tl = h.timeline();

// Previous tree
const prevArea = h.container({ x: 40, y: 56, w: 340, h: 348, label: 'Previous tree', role: 'neutral' });
const ulL = h.box({ x: 160, y: 100, w: 140, h: 56, label: '<ul>', role: 'neutral' });
const bobL = h.box({ x: 170, y: 188, w: 120, h: 48, label: 'Bob', role: 'neutral' });
const catL = h.box({ x: 170, y: 260, w: 120, h: 48, label: 'Cat', role: 'neutral' });
const kbL = h.token({ x: 105, y: 212, label: "key='b'", role: 'accent' });
const kcL = h.token({ x: 105, y: 284, label: "key='c'", role: 'accent' });

// New tree
const newArea = h.container({ x: 580, y: 56, w: 340, h: 348, label: 'New tree', role: 'neutral' });
const ulR = h.box({ x: 660, y: 100, w: 140, h: 56, label: '<ul>', role: 'neutral' });
const annR = h.box({ x: 670, y: 188, w: 120, h: 48, label: 'Ann', role: 'neutral' });
const bobR = h.box({ x: 670, y: 260, w: 120, h: 48, label: 'Bob', role: 'neutral' });
const catR = h.box({ x: 670, y: 332, w: 120, h: 48, label: 'Cat', role: 'neutral' });
const kaR = h.token({ x: 855, y: 212, label: "key='a'", role: 'accent' });
const kbR = h.token({ x: 855, y: 284, label: "key='b'", role: 'accent' });
const kcR = h.token({ x: 855, y: 356, label: "key='c'", role: 'accent' });
const insertTxt = h.text({ x: 628, y: 203, text: 'insert', size: 'small', anchor: 'middle', role: 'new' });

// Middle: old position matching, then key matching
const modeTxt = h.text({ x: 480, y: 72, text: 'match by position', size: 'label', anchor: 'middle', role: 'old' });
const pos1 = h.line({ x: 296, y: 212 }, { x: 664, y: 212 }, { role: 'old', dashed: true });
const pos2 = h.line({ x: 296, y: 284 }, { x: 664, y: 284 }, { role: 'old', dashed: true });
const keyB = h.line({ x: 296, y: 212 }, { x: 664, y: 284 }, { role: 'neutral' });
const keyC = h.line({ x: 296, y: 284 }, { x: 664, y: 356 }, { role: 'neutral' });

const note = h.note({ x: 300, y: 428, w: 360, text: 'Bob and Cat are kept, state and all. Only Ann is added.', role: 'accent' });

gsap.set([kbL, kcL, kaR, kbR, kcR, insertTxt, keyB, keyC, note], { opacity: 0 });

// 1) Scene: same lists as before, with the position matching
h.reveal(tl, [prevArea, ulL, bobL, catL, newArea, ulR, annR, bobR, catR], 0, { stagger: 0.05, duration: 0.6 });
h.reveal(tl, modeTxt, '>0.1', { from: 'down', duration: 0.5 });
h.draw(tl, pos1, '<', { duration: 0.6 });
h.draw(tl, pos2, '<0.15', { duration: 0.6 });

// 2) Give each item a key
h.reveal(tl, [kbL, kcL, kaR, kbR, kcR], '>0.5', { from: 'scale', stagger: 0.12, duration: 0.5 });
h.pulse(tl, [kbL, kcL, kaR, kbR, kcR], '>0.1');

// 3) Switch from position to key matching
h.hide(tl, [pos1, pos2], '>0.4');
h.swapText(tl, modeTxt, 'match by key', '<');
h.recolor(tl, modeTxt, 'active', '<');
h.recolor(tl, [bobL, bobR], 'active', '>0.2');
h.draw(tl, keyB, '<', { duration: 0.8 });
h.recolor(tl, [bobL, bobR], 'neutral', '>0.3');
h.recolor(tl, [catL, catR], 'active', '<');
h.draw(tl, keyC, '<', { duration: 0.8 });
h.recolor(tl, [catL, catR], 'neutral', '>0.3');

// 4) The one leftover: Ann is inserted
h.recolor(tl, annR, 'new', '>0.3');
h.reveal(tl, insertTxt, '<0.2', { from: 'left', duration: 0.5 });
h.highlight(tl, annR, '>0.1', { role: 'new', pad: 6 });

h.reveal(tl, note, '>0.4', { from: 'up' });
h.wait(tl, 2);
return tl;

// Layout plan:
// Top phase bar y 48..84: "Render phase" pill x 40..460, "Commit phase" pill x 500..920.
// Render side (x 40..460):
//   "Previous tree" container x 40..220, "New tree" container x 280..460, both y 108..324.
//   Item boxes w140 h32 at y 148 / 192 / 236 / 280 (left x 60, right x 300).
//   Dashed comparison lines cross the 100px gap between the two trees.
//   "List of changes" container x 160..460, y 348..492; items w220 h32 at x 200, y 392 and 440.
// Commit side: "Real DOM" container x 560..920, y 108..492.
//   <ul> x 590 y 156 (w120 h40); class tag x 740 y 158 (w140 h36);
//   li children x 740 (w140 h40) at y 236 (Ann, added), 304 (Bob), 372 (Cat).
// Arrows from list items (right edge x 420) go up-right to <ul> and to Ann in the Real DOM.
const tl = h.timeline();

// Phase bar
const renderBar = h.box({ x: 40, y: 48, w: 420, h: 36, label: 'Render phase', role: 'active', shape: 'pill', size: 'small' });
const commitBar = h.box({ x: 500, y: 48, w: 420, h: 36, label: 'Commit phase', role: 'muted', shape: 'pill', size: 'small' });

// Previous tree
const prevArea = h.container({ x: 40, y: 108, w: 180, h: 216, label: 'Previous tree', role: 'neutral' });
const ulL = h.box({ x: 60, y: 148, w: 140, h: 32, label: '<ul>', role: 'neutral', shape: 'pill', size: 'small' });
const bobL = h.box({ x: 60, y: 192, w: 140, h: 32, label: 'Bob', role: 'neutral', shape: 'pill', size: 'small' });
const catL = h.box({ x: 60, y: 236, w: 140, h: 32, label: 'Cat', role: 'neutral', shape: 'pill', size: 'small' });

// New tree
const newArea = h.container({ x: 280, y: 108, w: 180, h: 216, label: 'New tree', role: 'neutral' });
const ulR = h.box({ x: 300, y: 148, w: 140, h: 32, label: '<ul>', role: 'neutral', shape: 'pill', size: 'small' });
const annR = h.box({ x: 300, y: 192, w: 140, h: 32, label: 'Ann', role: 'new', shape: 'pill', size: 'small' });
const bobR = h.box({ x: 300, y: 236, w: 140, h: 32, label: 'Bob', role: 'neutral', shape: 'pill', size: 'small' });
const catR = h.box({ x: 300, y: 280, w: 140, h: 32, label: 'Cat', role: 'neutral', shape: 'pill', size: 'small' });

// Comparison lines
const cmpUl = h.line(ulL, ulR, { role: 'active', dashed: true });
const cmpBob = h.line(bobL, bobR, { role: 'active', dashed: true });
const cmpCat = h.line(catL, catR, { role: 'active', dashed: true });

// List of changes
const list = h.container({ x: 160, y: 348, w: 300, h: 144, label: 'List of changes', role: 'accent' });
const chIns = h.box({ x: 200, y: 392, w: 220, h: 32, label: 'insert Ann', role: 'new', shape: 'pill', size: 'small' });
const chUpd = h.box({ x: 200, y: 440, w: 220, h: 32, label: 'update class', role: 'new', shape: 'pill', size: 'small' });

// Real DOM
const dom = h.container({ x: 560, y: 108, w: 360, h: 384, label: 'Real DOM', role: 'neutral' });
const ulD = h.box({ x: 590, y: 156, w: 120, h: 40, label: '<ul>', role: 'neutral', shape: 'pill', size: 'small' });
const clsD = h.box({ x: 740, y: 158, w: 140, h: 36, label: "class='a'", role: 'accent', shape: 'pill', size: 'small' });
const annD = h.box({ x: 740, y: 236, w: 140, h: 40, label: 'Ann', role: 'new', shape: 'pill', size: 'small' });
const bobD = h.box({ x: 740, y: 304, w: 140, h: 40, label: 'Bob', role: 'neutral', shape: 'pill', size: 'small' });
const catD = h.box({ x: 740, y: 372, w: 140, h: 40, label: 'Cat', role: 'neutral', shape: 'pill', size: 'small' });
const eAnn = h.line(ulD, annD, { role: 'neutral', fromSide: 'bottom', toSide: 'left' });
const eBob = h.line(ulD, bobD, { role: 'neutral', fromSide: 'bottom', toSide: 'left' });
const eCat = h.line(ulD, catD, { role: 'neutral', fromSide: 'bottom', toSide: 'left' });

// Commit arrows
const aIns = h.arrow(chIns, annD, { role: 'new', fromSide: 'right', toSide: 'left' });
const aUpd = h.arrow(chUpd, ulD, { role: 'new', fromSide: 'right', toSide: 'left' });

gsap.set([cmpUl, cmpBob, cmpCat, chIns, chUpd, annD, eAnn, aIns, aUpd], { opacity: 0 });

// 1) Scene
h.reveal(tl, [renderBar, commitBar], 0, { stagger: 0.1, duration: 0.5 });
h.reveal(tl, [prevArea, ulL, bobL, catL, newArea, ulR, annR, bobR, catR], '<0.2', { stagger: 0.04, duration: 0.5 });
h.reveal(tl, [dom, ulD, clsD, bobD, catD, eBob, eCat], '<0.2', { stagger: 0.04, duration: 0.5 });
h.reveal(tl, list, '<0.2', { duration: 0.5 });

// 2) Render phase: compare and collect changes (page untouched)
h.pulse(tl, renderBar, '>0.3');
h.draw(tl, cmpUl, '>0.1', { duration: 0.6 });
h.draw(tl, cmpBob, '<0.2', { duration: 0.6 });
h.draw(tl, cmpCat, '<0.2', { duration: 0.6 });
h.pulse(tl, annR, '>0.2');
h.reveal(tl, chIns, '<', { from: 'left', duration: 0.6 });
h.pulse(tl, ulR, '>0.3');
h.reveal(tl, chUpd, '<', { from: 'left', duration: 0.6 });

// 3) Commit phase: apply all changes at once
h.recolor(tl, renderBar, 'muted', '>0.5');
h.recolor(tl, commitBar, 'active', '<');
h.dim(tl, [prevArea, ulL, bobL, catL, newArea, ulR, annR, bobR, catR, cmpUl, cmpBob, cmpCat], '<');
h.draw(tl, aIns, '>0.2', { duration: 0.7 });
h.draw(tl, aUpd, '<', { duration: 0.7 });
h.flow(tl, chIns, annD, '>', { label: '+', role: 'new', along: aIns, duration: 1.2 });
h.flow(tl, chUpd, ulD, '<', { label: '✎', role: 'new', along: aUpd, duration: 1.2 });
h.reveal(tl, [annD, eAnn], '>-0.1', { from: 'scale', stagger: 0, duration: 0.6 });
h.recolor(tl, ulD, 'new', '<');
h.swapText(tl, clsD, "class='b'", '<');
h.recolor(tl, clsD, 'new', '<');
const ring = h.highlight(tl, dom, '>0.2', { role: 'new', pad: 6 });
h.pulse(tl, [ulD, clsD, annD], '<0.1');

h.wait(tl, 2);
return tl;

// Layout: one horizontal timeline. Left container "Render phase · Fiber" x 40..700, y 100..300.
// Right container "Commit phase" x 724..920, y 100..300 (24px gap between phases).
// Unit-of-work blocks share the row y 168 (w 100, h 64, gap 24): x 64 / 188 / 312 / 436.
// The urgent update enters from below (x 312, y 344) into slot 3; units 3 and 4 shift right to x 436 / 560.
// The Commit block sits alone in the right container at x 748, y 168 (w 148). One note is centred below at y 440.
const tl = h.timeline();

const renderArea = h.container({ x: 40, y: 100, w: 660, h: 200, label: 'Render phase · Fiber', role: 'neutral' });
const commitArea = h.container({ x: 724, y: 100, w: 196, h: 200, label: 'Commit phase', role: 'neutral' });

const BW = 100, BH = 64, rowY = 168;
const xs = [64, 188, 312, 436];
const units = xs.map((x, i) => h.box({ x, y: rowY, w: BW, h: BH, label: 'unit of work', sub: 'fiber ' + (i + 1), role: 'neutral', size: 'body' }));

const urgent = h.box({ x: 312, y: 344, w: BW, h: BH, label: 'urgent update', sub: 'keypress', role: 'accent', size: 'body' });
const commit = h.box({ x: 748, y: rowY, w: 148, h: BH, label: 'Commit', sub: 'never split', role: 'active' });

const n = h.note({ x: 240, y: 440, w: 480, text: 'Render work can pause between units. Commit runs in one go.', role: 'accent' });

gsap.set([urgent, commit, n], { opacity: 0 });

// 1) Scene: the render phase, now split into small units
h.reveal(tl, [renderArea, commitArea], 0, { stagger: 0.15, duration: 0.6 });
h.reveal(tl, units, '>0.1', { from: 'left', stagger: 0.12, duration: 0.5 });

// React works through units one at a time
h.recolor(tl, units[0], 'active', '>0.4');
h.recolor(tl, units[0], 'new', '>0.2');
h.recolor(tl, units[1], 'active', '<');
h.recolor(tl, units[1], 'new', '>0.2');

// 2) The change: an urgent update arrives and cuts in
h.reveal(tl, urgent, '>0.4', { from: 'up', duration: 0.6 });
h.pulse(tl, urgent, '>0.1');
h.moveTo(tl, units[3], { x: 560 }, '>0.3', { duration: 0.8 });
h.moveTo(tl, units[2], { x: 436 }, '<', { duration: 0.8 });
h.moveTo(tl, urgent, { y: rowY }, '>0.1', { duration: 0.8 });
const ring = h.highlight(tl, urgent, '>0.1', { role: 'accent', pad: 8 });
h.recolor(tl, urgent, 'new', '>0.3');
h.hide(tl, ring, '>0.2');

// Render work resumes where it left off
h.recolor(tl, units[2], 'active', '>0.4');
h.recolor(tl, units[2], 'new', '>0.2');
h.recolor(tl, units[3], 'active', '<');
h.recolor(tl, units[3], 'new', '>0.2');

// 3) Commit: one solid, unbroken block
h.reveal(tl, commit, '>0.5', { from: 'scale', duration: 0.6 });
h.pulse(tl, commit, '>0.1');
h.recolor(tl, commit, 'new', '>0.3');

h.reveal(tl, n, '>0.5', { from: 'up' });
h.wait(tl, 2);
return tl;
